# ----------------------------------------------------------------------
# configuration (secrets -> env -> UI overrides)
# ----------------------------------------------------------------------
def _plain(obj, depth: int = 0):
    """Secrets/AttrDict -> plain dict, recursively (Streamlit's special dicts
    do not always survive ``dict(...)`` and silently lose their sections)."""
    if depth > 4:
        return str(obj)
    try:
        if hasattr(obj, "keys"):
            return {str(k): _plain(obj[k], depth + 1) for k in obj.keys()}
        if isinstance(obj, (list, tuple)):
            return [_plain(v, depth + 1) for v in obj]
    except Exception:                                            # noqa: BLE001
        return str(obj)
    return obj


def secrets_dict():
    """Everything the app knows about keys: Streamlit secrets, then the raw
    ``.streamlit/secrets.toml`` file on disk as a second chance."""
    out = {}
    try:
        out = _plain(st.secrets)
        if not isinstance(out, dict):
            out = {}
    except Exception:                                            # noqa: BLE001
        out = {}
    if not out:
        for _p in (os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                ".streamlit", "secrets.toml"),
                   os.path.join(os.getcwd(), ".streamlit", "secrets.toml")):
            try:
                if not os.path.exists(_p):
                    continue
                try:
                    import tomllib as _tl
                except Exception:                                # noqa: BLE001
                    import tomli as _tl                        # type: ignore
                with open(_p, "rb") as fh:
                    out = _plain(_tl.load(fh))
                if out:
                    break
            except Exception:                                    # noqa: BLE001
                continue
    return out if isinstance(out, dict) else {}


def build_config() -> Config:
    cfg = Config.from_sources(secrets_dict())
    s = st.session_state
    # UI values may only OVERRIDE a secret when the user actually typed one.
    # The old line (`= s.get(...) or ""`) wrote an empty string back every time
    # the Settings tab rendered, so a token saved in secrets.toml silently
    # disappeared and Dhan showed OFF.
    _ui_id = (s.get("ui_dhan_id") or "").strip()
    _ui_tok = (s.get("ui_dhan_token") or "").strip()
    if _ui_id:
        cfg.dhan_client_id = _ui_id
    if _ui_tok:
        cfg.dhan_access_token = _ui_tok
    cfg.dhan_enabled = bool((cfg.dhan_client_id or "").strip()
                            and (cfg.dhan_access_token or "").strip())
    cfg.dhan_ws_enabled = bool(s.get("ui_dhan_ws", cfg.dhan_ws_enabled))
    if s.get("ui_llm_provider"):
        cfg.llm_provider = s["ui_llm_provider"]
    if s.get("ui_llm_key"):
        cfg.llm_api_key = s["ui_llm_key"]
    if s.get("ui_llm_model"):
        cfg.llm_model = s["ui_llm_model"]
    cfg.ai_mode = "paid" if (cfg.llm_provider and cfg.llm_api_key) else "free"
    cfg.refresh_seconds = int(s.get("ui_refresh", cfg.refresh_seconds))
    cfg.capital = float(s.get("ui_capital", cfg.capital))
    cfg.risk_per_trade_pct = float(s.get("ui_risk", cfg.risk_per_trade_pct))
    cfg.zone_target_rr = float(s.get("ui_rr", cfg.zone_target_rr))
    cfg.zone_legout_mult = float(s.get("ui_legout", cfg.zone_legout_mult))
    cfg.zone_max_wick_pct = float(s.get("ui_wick", cfg.zone_max_wick_pct))
    cfg.zone_sl_buffer_atr = float(s.get("ui_slbuf", cfg.zone_sl_buffer_atr))
    cfg.zone_eod_filter = bool(s.get("ui_eod", cfg.zone_eod_filter))
    cfg.yahoo_enabled = bool(s.get("ui_yahoo", cfg.yahoo_enabled))
    cfg.nse_enabled = bool(s.get("ui_nse", cfg.nse_enabled))
    cfg.news_enabled = bool(s.get("ui_news", cfg.news_enabled))

    # --- news intelligence ------------------------------------------------
    cfg.firecrawl_api_key = s.get("ui_fc_key", cfg.firecrawl_api_key) or ""
