# ----------------------------------------------------------------------
# last good snapshot on disk  (instant first paint on a cold session)
# ----------------------------------------------------------------------
def _state_cache_path() -> str:
    try:
        d = build_config().cache_dir or "data"
    except Exception:                                            # noqa: BLE001
        d = "data"
    return os.path.join(d, "last_state.json")


def _iso_asof(a) -> str:
    """ISO stamp for the snapshot file - aware if possible, never raises.
    ``state.asof`` is already IST wall-clock (naive), so only the zone is added."""
    try:
        if a is None:
            return ""
        if getattr(a, "tzinfo", None) is not None:
            return a.isoformat()
        return a.replace(tzinfo=timezone(IST)).isoformat()
    except Exception:                                            # noqa: BLE001
        return ""


def save_last_state(st) -> None:
    """Persist just enough to paint the screen while the next cycle runs."""
    try:
        import json
        payload = {
            "asof": _iso_asof(st.asof),
            "features": st.features or [],
            "zones": st.zones or [],
            "breadth": st.breadth or {},
            "news": (st.news or [])[:40],
            "sources": st.sources or {},
            "market_open": bool(getattr(st, "market_open", False)),
            "saved_at": time.time(),
        }
        _path = _state_cache_path()
        os.makedirs(os.path.dirname(_path) or ".", exist_ok=True)
        with open(_path, "w", encoding="utf-8") as fh:
            json.dump(payload, fh, default=str)
    except Exception:                                            # noqa: BLE001
        pass


def load_last_state(max_age_min: float = 10.0):
    """-> MarketState from the last cycle, or None (never raises)."""
    try:
        import json
        _path = _state_cache_path()
        if not os.path.exists(_path):
            return None
        with open(_path, encoding="utf-8") as fh:
            d = json.load(fh)
        if time.time() - float(d.get("saved_at") or 0) > max_age_min * 60:
            return None
        st_ = MarketState(cfg=build_config())
        st_.features = d.get("features") or []
        st_.zones = d.get("zones") or []
        st_.breadth = d.get("breadth") or {}
        st_.news = d.get("news") or []
        st_.sources = d.get("sources") or {}
        st_.market_open = bool(d.get("market_open"))
        try:
            st_.asof = datetime.fromisoformat(d.get("asof"))
            if st_.asof and st_.asof.tzinfo is None:
                st_.asof = st_.asof.replace(tzinfo=IST)
        except Exception:                                        # noqa: BLE001
            st_.asof = None
        st_.notes = {"cached": True, "lite": True}
        return st_ if st_.features else None
    except Exception:                                            # noqa: BLE001
        return None


# ---------------- run the workflow ---------------------------------------
# Cold session?  Paint the previous snapshot FIRST (a few hundred ms), then run
# the live cycle and replace it.  This is what keeps "Agents working" from
# looking like a dead app on a slow phone network.
_COLD = st.session_state.get("state") is None
_PAINT = st.empty()          # holds the stale snapshot; emptied when fresh data lands
if _COLD:
    _prev = load_last_state()
    if _prev is not None and _prev.features:
        _age = 0.0
        try:
            _a = _prev.asof
            if _a is not None:
                if _a.tzinfo is None:                 # stored without a zone -> IST
                    _a = _a.replace(tzinfo=timezone(IST))
                _age = max(0.0, (datetime.now(timezone(IST)) - _a
                                 ).total_seconds() / 60.0)
        except Exception:                                        # noqa: BLE001
            _age = 0.0
        _px = pd.DataFrame(_prev.features)
        _ph = _PAINT.container()
        _ph.markdown(
            f'<div style="background:#0c1017;border:1px solid #f59e0b55;border-radius:6px;'
            f'padding:6px 9px;font-size:11px;line-height:1.5;margin-bottom:4px">'
            f'⚡ <b>पिछला स्नैपशॉट</b> '
            f'{_prev.asof.strftime("%d-%b %H:%M") if _prev.asof else "—"} IST ' 
            f'({_age:.0f} मिनट पुराना) — ताज़ा डेटा लोड हो रहा है…<br>'
            f'<span style="color:#9aa4b2">{len(_px)} स्टॉक्स · ज़ोन '
            f'{len(_prev.zones or [])} · यह नंबर पुराने हैं, नीचे ताज़ा आएँगे</span></div>',
            unsafe_allow_html=True)
        _c1 = _ph.columns(3)
        if "Final AI Bias" in _px.columns and "Raw_Score" in _px.columns:
            _top = _px.reindex(_px["Raw_Score"].abs().sort_values(ascending=False).index).head(3)
            for _i, (_, _r) in enumerate(_top.iterrows()):
                _c1[_i % 3].caption(f"**{_r['Raw_Symbol']}** {_r['Final AI Bias']} · "
                                    f"{_r['AI Score']}")
try:
    state = run_cycle(cfg)
    orch = st.session_state["orch"]
except Exception as exc:                                     # noqa: BLE001
    st.error(f"Agent workflow failed: {type(exc).__name__}: {exc}")
    st.code(traceback.format_exc(limit=4))
    st.stop()

