with tab_zone:
    from terminal.engine import zschedule as _zs
    cfg = build_config()

    # cold start / new slot -> build the zones BEFORE drawing the table
    if (not st.session_state.get("zone_rows_cache")
            or st.session_state.get("zone_dirty")) \
            and not st.session_state.get("zone_boot_tried"):
        st.session_state["zone_boot_tried"] = True
        with st.spinner("ज़ोन एजेंट पहला स्कैन बना रहा है (सिर्फ़ एक बार) …"):
            run_zone_scan(cfg, force=True, scope="Top 18")

    _slot = _zs.slot_state()
    _rng_pct = float(st.session_state.get("ui_zone_range", 10.0))
    _last = st.session_state.get("zone_last_ts", 0)
    _last_txt = (datetime.fromtimestamp(_last, timezone.utc) + IST).strftime("%H:%M:%S") \
        if _last else "—"
    _zrows = list(state.zones or [])
    _side_of = lambda r: r.get("demand/Supply") or r.get("Side") or ""      # noqa: E731
    _bias_of = lambda r: r.get("AI Bias") or r.get("Bias") or ""            # noqa: E731
    def _gap_pct(r) -> float:
        """Distance of live price from the zone's proximal edge (%)."""
        try:
            px = float(_LIVE_PX.get(r.get("Symbol")) or r.get("LTP") or 0)
            prox = float(r.get("Entry (Proximal)") or 0)
            return abs(px - prox) / prox * 100.0 if prox and px else 999.0
        except (TypeError, ValueError, ZeroDivisionError):
            return 999.0

    _aligned = [r for r in _zrows
                if r.get("Zone State") == "Fresh"
                and (("Demand" in _side_of(r) and _bias_of(r) in ("BUY", "STRONG BUY"))
                     or ("Supply" in _side_of(r) and _bias_of(r) in ("SELL", "STRONG SELL")))]

    def _score_abs(r) -> float:
        try:
            return abs(float(str(r.get("AI Score", "0")).split("/")[0].replace("+", "")))
        except (TypeError, ValueError):
            return 0.0

    def _tf_rank(tf: str) -> int:
        try:
            return ZONE_TFS_ALL.index(str(tf))
        except ValueError:
            return len(ZONE_TFS_ALL)

    # NEAREST ZONE FIRST - 3m या 1M, कोई फ़र्क़ नहीं.  हर ज़ोन अपनी दूरी से
    # क्रम में आता है; बराबर दूरी पर मज़बूत स्कोर, फिर छोटा TF पहले.
    _tf_of = lambda r: str(r.get("Near Timeframe") or r.get("tf") or "")   # noqa: E731
    _ranked = sorted(_aligned,
                     key=lambda r: (_gap_pct(r), -_score_abs(r), _tf_rank(_tf_of(r))))
    _total_ready = len(_ranked)
    # एक स्टॉक = एक पंक्ति: उसका सबसे नज़दीकी ज़ोन (चाहे कोई भी TF हो).
    # बाक़ी TF के ज़ोन नीचे "पूरा ज़ोन स्कैनर" में पड़े रहते हैं.
    _seen_sym, _ready = set(), []
    for _r in _ranked:
        _sy = _r.get("Symbol")
        if _sy in _seen_sym:
            continue
        _seen_sym.add(_sy)
        _ready.append(_r)
    _live = [r for r in _zrows if str(r.get("Zone State")) == "Fresh"]
    _age_min = (time.time() - _last) / 60.0 if _last else 999.0
    _now_ist = _zs.now_ist()
    _session_now = (_now_ist.weekday() < 5 and (_now_ist.hour, _now_ist.minute) >= (9, 15)
                    and _now_ist.hour < 16)
    _stale = bool(_session_now and _age_min > 10.0 and _zrows)

    # ================= CLEAN TABLE FIRST ================================
    # टेबल से ऊपर सिर्फ़ एक पतली लाइन + स्कैन बटन.  कोई सेटिंग, टाइटल या रेडियो नहीं.
    _view = _ready[:30]
    _b1, _b2 = st.columns([5, 1])
    with _b1:
        st.markdown(
            f'<div style="font-size:10.5px;color:#9aa4b2;line-height:1.6;padding-top:4px">'
            f'🎯 <b style="color:#d1d4dc">{len(_view)}</b>/{_total_ready} नज़दीकी पहले · '
            f'{len(_zrows)} ज़ोन · स्कैन <b>{_last_txt}</b> IST · '
            f'अगला <b>{_slot["next_slot"]:%H:%M}</b> · ±{_rng_pct:.0f}%'
            + (f' · <span style="color:#f59e0b">⚠ {_age_min:.0f} मि पुराना</span>'
               if _stale else "")
            + '</div>', unsafe_allow_html=True)
    with _b2:
        if st.button("🚀 स्कैन", **container_kw(), use_container_width=True):
            st.session_state["zone_last_ts"] = 0
            st.session_state["zone_full_ladder_done"] = True
            st.session_state["zone_full_ladder"] = True
            run_zone_scan(cfg, force=True)
            st.session_state["zone_full_ladder"] = False
            st.rerun()

    _show_zone_frame(_zone_frame(_view))

    st.caption("हर TF (3m → 1M) के ज़ोन, दूरी के हिसाब से — नज़दीकी सबसे ऊपर · "
               "स्टॉक/फ्यूचर्स नाम टैप = उसी TF का चार्ट"
               + ("  ·  ⏳ यह तेज़ पहला पेज है (5m/15m/1h/1d), बाक़ी TF अगले रिफ़्रेश पर"
                  if st.session_state.get("lite_paint") else ""))

    if _ready:
        _b = _ready[0]                      # सबसे नज़दीकी ज़ोन
        st.markdown(
            f'<div style="background:rgba(8,153,129,.10);border-left:3px solid #089981;'
            f'padding:4px 8px;border-radius:5px;font-size:11px;margin:2px 0">'
            f'सबसे नज़दीक: <b>{_b.get("Symbol")}</b> · {_b.get("demand/Supply")} '
            f'{_b.get("Near Timeframe")} · दूरी {_gap_pct(_b):.2f}% · '
            f'{_b.get("AI Score")} · एंट्री ₹{float(_b.get("Entry (Proximal)") or 0):,.2f} · '
            f'SL ₹{float(_b.get("Distal SL") or 0):,.2f} · '
            f'टारगेट ₹{float(_b.get("Target Price") or 0):,.2f} · '
            f'Qty {_b.get("Qty")}</div>', unsafe_allow_html=True)
        _verdict_block(str(_b.get("Symbol")), key="zone_why", card=False)

    with st.expander(f"📍 {cfg.zone_watch_pct}% के अंदर — लाइव प्रॉक्सिमिटी"):
        _near = st.session_state.get("zone_watch_live") or []
        if not _near:
            try:
                _near = approaching(zone_rows(UNIVERSE, tf=cfg.zone_watch_tf,
                                              max_symbols=cfg.zone_watch_max_symbols),
                                    cfg.zone_watch_pct)
            except Exception:                                    # noqa: BLE001
                _near = []
        if _near:
            _ndf = pd.DataFrame(_near)
            _ndf["Symbol"] = _ndf["Symbol"].map(lambda s: _chart_url(s, "15m", fut=False))
            st.dataframe(_ndf.style.format({"Gap %": "{:.2f}%", "LTP": "₹{:.2f}",
                                            "Proximal": "₹{:.2f}", "Distal": "₹{:.2f}"},
                                           na_rep="—"),
                         column_config={"Symbol": st.column_config.LinkColumn(
                             "Symbol", display_text=r"symbol=NSE%3A([A-Z0-9%&.-]*)&")},
                         hide_index=True, height=260, **container_kw())
        else:
            st.caption("अभी कोई स्टॉक इस सीमा के अंदर नहीं।")

    with st.expander(f"🗂️ पूरा ज़ोन स्कैनर ({len(_zrows)} पंक्तियाँ)"):
        if _zrows:
            zdf = pd.DataFrame(_zrows)
            f1, f2, f3 = st.columns(3)
            side = f1.multiselect("साइड", sorted(zdf["demand/Supply"].dropna().unique()),
                                  default=None, placeholder="सभी")
            fresh = f2.multiselect("स्थिति", sorted(zdf["Zone State"].dropna().unique()),
                                   default=["Fresh"], placeholder="Fresh")
            tfs = f3.multiselect("TF", sorted(zdf["Near Timeframe"].dropna().unique()),
                                 default=None, placeholder="सभी")
            filt = zdf.copy()
            if side:
                filt = filt[filt["demand/Supply"].isin(side)]
            if fresh:
                filt = filt[filt["Zone State"].isin(fresh)]
            if tfs:
                filt = filt[filt["Near Timeframe"].isin(tfs)]
            # live price + distance + futures provenance on every row
            filt["LTP"] = filt["Symbol"].map(
                lambda x: _LIVE_PX.get(x) or filt.loc[filt["Symbol"] == x, "LTP"].iloc[0])
            filt["Futures"] = filt["Symbol"].map(lambda x: _fut_info(x)[0])
            filt["फ्यू. समय"] = filt["Symbol"].map(lambda x: _fut_info(x)[1])
            filt["दूरी %"] = filt.apply(
                lambda r: round(abs(float(r["LTP"]) - float(r["Entry (Proximal)"]))
                                / float(r["Entry (Proximal)"]) * 100, 2), axis=1)
            display_zone_table(filt, st.session_state.get("tf_master", "1d"),
                               verify_map=(state.notes or {}).get("verify_rows") or {})
            st.caption(f"स्रोत: NSE/Yahoo कैंडल · स्कैन {_last_txt} IST · "
                       f"रेंज ±{_rng_pct:.0f}% · दो-स्रोत जाँच LTP पर लागू")
        else:
            _rep = (( st.session_state.get("zone_meta") or {}).get("report") or {})
            st.warning("इस स्कैन में ज़ोन नहीं बने — 🚀 अभी स्कैन दबाएँ।"
                       + (f" कारण: {(_rep.get('notes') or ['—'])[-1]}" if _rep else ""))

# ======================================================================
# TAB 2 - मार्केट  (मास्टर तालिका + सहायक डेटा)
# ======================================================================
with tab_market:
    render_breadth(BREADTH, QSNAP.stamp if QSNAP.ok else "—")
    df = pd.DataFrame(state.features)

    # real bhavcopy futures where available
    if not df.empty:
        _fo = BHAV.futures_oi()
        if not _fo.empty:
            _m = _fo.set_index("Symbol")
            _real_ltp = df["Raw_Symbol"].map(_m["Fut LTP"])
            _mask = _real_ltp.notna()
            if _mask.any():
                df.loc[_mask, "Futures LTP (Cur-M)"] = _real_ltp[_mask]
                df.loc[_mask, "Data Source"] = "NSE bhavcopy (EOD)"
                _real_oi = df["Raw_Symbol"].map(_m["Fut OI Chg %"])
                _cur = pd.to_numeric(df["Futures OI Chg %"].astype(str)
                                     .str.replace("%", "", regex=False), errors="coerce")
                _cur = _cur.mask(_real_oi.notna(), _real_oi)
                df["Futures OI Chg %"] = _cur.map(
                    lambda v: f"{v:+.2f}%" if pd.notna(v) else "n/a")
        df["Futures LTP (Cur-M)"] = pd.to_numeric(
            df["Futures LTP (Cur-M)"], errors="coerce").fillna(0.0).round(2)
        # basis must compare like with like: when the futures leg is the official
        # EOD close, the reference is that same session's cash close
        _spot = pd.to_numeric(df["Spot LTP"], errors="coerce")
        _chg = pd.to_numeric(df["Spot Chg %"], errors="coerce").fillna(0.0)
        _prev = _spot / (1 + _chg / 100.0)
        _eod = df["Data Source"].astype(str).str.contains("bhavcopy", na=False)
        try:
            _cash = BHAV.cash_close()
        except Exception:                                        # noqa: BLE001
            _cash = {}
        _same = df["Raw_Symbol"].map(_cash)
        _ref = _same.where(_eod & _same.notna(), _prev.where(_eod, _spot))
        df["Dif. %"] = ((df["Futures LTP (Cur-M)"] - _ref) / _ref * 100).round(2).fillna(0.0)

    if df.empty:
        st.warning("फ़ीड में कोई पंक्ति नहीं — ⚙️ सेटिंग → डेटा सोर्स देखें।")
    else:
        f1, f2, f3 = st.columns([1.6, 1.05, 1.05])
        search = f1.text_input("🔎 स्टॉक", "", key="sym_filter",
                               label_visibility="collapsed", placeholder="🔎 स्टॉक खोजें")
        bias_filter = f2.multiselect("Bias", ["STRONG BUY", "BUY", "AVOID TRADE",
                                              "SELL", "STRONG SELL"], default=[],
                                     label_visibility="collapsed", placeholder="Bias")
